function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;

    const n = tab.length;
    const dp = new Array(n).fill(1);
    const pos = [];

    for (let i = 0; i < n; i++) {
        let lo = 0, hi = i - 1;
        while (lo <= hi) {
            const mid = Math.floor((lo + hi) / 2);
            if (dp[mid] < dp[i]) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        pos[dp[i]] = i;
    }

    let maxLen = 0;
    for (let i = n - 1; i >= 0; i--) {
        if (pos[i] !== undefined) {
            maxLen = Math.max(maxLen, dp[pos[i]]);
        }
    }

    return maxLen;
}
